CREATE TEMPORARY VIEW br_registraton_state_${grass_region_without_quote} AS
SELECT DISTINCT
    user_id
    ,CASE
        WHEN registration_state = 'Sao Paulo' THEN 'Sao Paulo'
        WHEN registration_state = 'Rio de Janeiro' THEN 'Rio de Janeiro'
        ELSE 'others'
    END AS detail_state
FROM
    traffic.dwd_register_di__reg_live
WHERE
    ${grass_region} = 'BR'
    AND grass_region = ${grass_region}
    AND registration_country = ${grass_region}
    AND user_id > 0;

--sql_divide_splitter--

CREATE TEMPORARY VIEW br_buyer_shipping_state_${grass_region_without_quote} AS
SELECT
    buyer_id AS user_id
    ,CASE
        WHEN buyer_shipping_address_state = 'São Paulo' THEN 'Sao Paulo'
        WHEN buyer_shipping_address_state = 'Rio de Janeiro' THEN 'Rio de Janeiro'
        ELSE 'others'
    END AS detail_state
    ,ROW_NUMBER() OVER (PARTITION BY buyer_id ORDER BY create_datetime DESC) AS order_dt
FROM
    mp_order.dwd_order_item_all_ent_df__reg_s0_live
WHERE
    ${grass_region} = 'BR'
    AND grass_date BETWEEN DATE_SUB(${local_date}, 59) AND ${local_date}
    AND grass_region = ${grass_region}
    AND tz_type = 'local'
    AND DATE(create_datetime) BETWEEN DATE_SUB(${local_date}, 29) AND ${local_date}
    AND buyer_shipping_address_state IS NOT NULL;

--sql_divide_splitter--

CREATE TEMPORARY VIEW br_buyer_shipping_state_first_${grass_region_without_quote} AS
SELECT
    user_id
    ,detail_state
FROM
    br_buyer_shipping_state_${grass_region_without_quote}
WHERE
    order_dt = 1;

--sql_divide_splitter--

CREATE TEMPORARY VIEW br_user_state_mapping_${grass_region_without_quote} AS
SELECT
    a.user_id AS user_id
    ,CASE
        WHEN b.user_id IS NOT NULL THEN b.detail_state
        ELSE a.detail_state
    END AS state
FROM
    br_registraton_state_${grass_region_without_quote} a
LEFT JOIN
    br_buyer_shipping_state_first_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
GROUP BY 1, 2;

--sql_divide_splitter--

CREATE TEMPORARY VIEW vn_default_delivery_state_${grass_region_without_quote} AS
SELECT
    user_id
    ,major_region AS state
FROM
    mp_user.dim_user__reg_s0_live a
LEFT JOIN
    vnbi_mkt.shopee_vn_bi_team__vietnam_region_map_details b
ON
    a.default_delivery_address_state = b.province
WHERE
    ${grass_region} = 'VN'
    AND grass_region = ${grass_region}
    AND grass_date = ${local_date}
    AND is_backend_created = 0;

--sql_divide_splitter--

CREATE TEMPORARY VIEW vn_last_shipping_province_${grass_region_without_quote} AS
SELECT
    a.user_id AS user_id
    ,major_region AS state
FROM
    mp_user.dim_user__reg_s0_live a
LEFT JOIN
    vnbi_mkt.dim_user__address b
ON
    a.user_id = b.user_id
LEFT JOIN
    vnbi_mkt.shopee_vn_bi_team__vietnam_region_map_details c
ON
    b.last_shipping_province = c.province
WHERE
    ${grass_region} = 'VN'
    AND grass_region = ${grass_region}
    AND grass_date = ${local_date}
    AND is_backend_created = 0;

--sql_divide_splitter--

CREATE TEMPORARY VIEW vn_registration_state_${grass_region_without_quote} AS
SELECT
    a.user_id AS user_id
    ,major_region AS state
FROM
    mp_user.dim_user__reg_s0_live a
LEFT JOIN
    mp_user.dwd_register_ent_di__vn_s0_live b
ON
    a.user_id = b.user_id
LEFT JOIN
    vnbi_mkt.shopee_vn_bi_team__vietnam_region_map_details c
ON
    b.registration_state = c.province_reg
WHERE
    ${grass_region} = 'VN'
    AND a.grass_region = ${grass_region}
    AND a.grass_date = ${local_date}
    AND a.is_backend_created = 0
    AND b.registration_country = 'VN'
    AND b.registration_state != '-';

