CREATE TEMPORARY VIEW vn_user_state_mapping_${grass_region_without_quote} AS
SELECT DISTINCT
    a.user_id AS user_id
    ,COALESCE(a.state, b.state, c.state, 'Unknown') AS state
FROM
    vn_default_delivery_state_${grass_region_without_quote} a
LEFT JOIN
    vn_last_shipping_province_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
LEFT JOIN
    vn_registration_state_${grass_region_without_quote} c
ON
    a.user_id = c.user_id;

