    ,platform
    ,is_ads
    ,feature_detail
    ,source1_feature_detail
    ,source2_feature_detail

    ,concat('dpm business line ', reporting_business_line) as reporting_business_line
    ,concat('dpm module ', reporting_module, ' business line ', reporting_business_line) as reporting_module
    ,concat('dpm reporting object ', reporting_object, ' module ', reporting_module, ' business line ', reporting_business_line) as reporting_object
    ,concat('dpm mapping group ', feature_group) as feature_group
    ,algo_tag
    ,concat('Page ', split(if(feature_detail ='', null, feature_detail), '-')[0]) as mapped_page_type

    ,concat('dpm business line ', source1_reporting_business_line) as source1_reporting_business_line
    ,concat('dpm module ', source1_reporting_module, ' business line ', source1_reporting_business_line) as source1_reporting_module
    ,concat('dpm reporting object ', source1_reporting_object, ' module ', source1_reporting_module, ' business line ', source1_reporting_business_line) as source1_reporting_object
    ,concat('dpm mapping group ', source1_feature_group) as source1_feature_group
    ,source1_algo_tag
    ,concat('Page ', split(if(source1_feature_detail = '', null, source1_feature_detail), '-')[0]) as source1_mapped_page_type

    ,concat('dpm business line ', source2_reporting_business_line) as source2_reporting_business_line
    ,concat('dpm module ', source2_reporting_module, ' business line ', source2_reporting_business_line) as source2_reporting_module
    ,concat('dpm reporting object ', source2_reporting_object, ' module ', source2_reporting_module, ' business line ', source2_reporting_business_line) as source2_reporting_object
    ,concat('dpm mapping group ', source2_feature_group) as source2_feature_group
    ,source2_algo_tag
    ,concat('Page ', split(if(source2_feature_detail = '', null, source2_feature_detail), '-')[0]) as source2_mapped_page_type

    ,net_order_cnt
    ,nmv
    ,local_date
from srdi_mart.dwd_sr_data_warehouse_platform_nmv
where
    grass_region in (${grass_region})
    and local_date between date_add(date(${local_date}), -7) and date(${local_date})
;

