create temporary view filter_tag_data_${grass_region_without_quote} AS
select
    *,
    if(split(feature_detail,'-')[2] is not null, split(feature_detail,'-')[2], split(feature_detail,'-')[1]) as target_type
from
    raw_data_${grass_region_without_quote}
;

--sql_divide_splitter--
create temporary view cube_table_${grass_region_without_quote} AS
select
    local_date
    ,feature_detail
    ,is_ads
    ,platform
    ,target_type
    ,user_id
    ,scenario_tag
    ,state

    ,sum(net_order_cnt) as net_order_cnt
    ,sum(nmv) as nmv
from filter_tag_data_${grass_region_without_quote}
LATERAL VIEW OUTER EXPLODE(FILTER(scenario_tags, value -> value is not null)) as scenario_tag
group by grouping sets (
    -- Base dimension local_date, feature_detail, target_type, scenario_tag. Cube dimension is_ads, platform
     (local_date, feature_detail, target_type, user_id, scenario_tag, state)
    ,(local_date, feature_detail, target_type, user_id, scenario_tag, state, is_ads)
    ,(local_date, feature_detail, target_type, user_id, scenario_tag, state, platform)
    ,(local_date, feature_detail, target_type, user_id, scenario_tag, state, is_ads, platform)

    -- Base dimension local_date, target_type, scenario_tag. Cube dimension is_ads, platform
    ,(local_date, target_type, user_id, scenario_tag, state)
    ,(local_date, target_type, user_id, scenario_tag, state, is_ads)
    ,(local_date, target_type, user_id, scenario_tag, state, platform)
    ,(local_date, target_type, user_id, scenario_tag, state, is_ads, platform)
)
union all
select
    local_date
    ,'__ALL__' as feature_detail
    ,is_ads
    ,platform
    ,'__ALL__' as target_type
    ,user_id
    ,'__ALL__' as scenario_tag
    ,state

    ,sum(net_order_cnt) as net_order_cnt
    ,sum(nmv) as nmv
from
    base_table_${grass_region_without_quote}
group by grouping sets (
    -- Base dimension local_date. Cube dimension is_ads, platform
     (local_date, user_id, state)
    ,(local_date, user_id, state, is_ads)
    ,(local_date, user_id, state, platform)
    ,(local_date, user_id, state, is_ads, platform)
)
union all
select
    local_date
    ,'__ALL__' as feature_detail
    ,is_ads
    ,platform
    ,'__ALL__' as target_type
    ,user_id
    ,scenario_tag
    ,state

    ,sum(net_order_cnt) as net_order_cnt
    ,sum(nmv) as nmv
from
    base_table_${grass_region_without_quote}
LATERAL VIEW OUTER EXPLODE(FILTER(array_union(array_union(coalesce(scenario_tags, array()), coalesce(source1_scenario_tags, array())), coalesce(source2_scenario_tags, array())), value -> value is not null)) as scenario_tag
group by grouping sets (
    -- Base dimension local_date, scenario_tag. Cube dimension is_ads, platform
     (local_date, user_id, scenario_tag, state)
    ,(local_date, user_id, scenario_tag, state, is_ads)
    ,(local_date, user_id, scenario_tag, state, platform)
    ,(local_date, user_id, scenario_tag, state, is_ads, platform)
);

