CREATE TEMPORARY VIEW uu_data_${grass_region_without_quote} AS
SELECT
    *
    ,if(net_order_cnt > 0 and user_id > 0, 1, 0) AS net_order_uu
FROM
    cube_table_${grass_region_without_quote};


--sql_divide_splitter--
create TEMPORARY VIEW map_data_${grass_region_without_quote} as
select
    local_date
    ,state
    ,platform
    ,is_ads
    ,scenario_tag
    ,feature_detail
    ,target_type
    ,user_id
    ,array(
        net_order_uu
        ,net_order_cnt
        ,nmv
    ) as metrics
from
    uu_data_${grass_region_without_quote};

--sql_divide_splitter--
create temporary view metric_table_${grass_region_without_quote} AS
select
    t1.local_date
    ,state
    ,if(platform is null, '__ALL__', platform) as platform
    ,if(is_ads is null, '__ALL__', is_ads) as is_ads
    ,scenario_tag
    ,if(feature_detail is null, '__ALL__', feature_detail) as feature_detail
    ,if(target_type is null, '__ALL__', target_type) as target_type
    ,exp_sum(t2.exp_group_ids, t1.metrics) as exp_metrics
from
    map_data_${grass_region_without_quote} as t1
inner join
    user_exp_${grass_region_without_quote} as t2
on
    t1.user_id = t2.user_id
    and t1.local_date = t2.local_date
group by
    1, 2, 3, 4, 5, 6, 7;

--sql_divide_splitter--
create temporary view explode_metric_table_${grass_region_without_quote} AS
select
    local_date
    ,state
    ,platform
    ,is_ads
    ,scenario_tag
    ,feature_detail
    ,target_type
    ,exp_info.exp_group_id as exp_group_id
    ,cast(exp_info.fields[0] as bigint) as net_order_uu
    ,exp_info.fields[1] as net_order_cnt
    ,exp_info.fields[2] as nmv
from
    metric_table_${grass_region_without_quote}
    LATERAL VIEW EXPLODE(exp_metrics) as exp_info
;

--sql_divide_splitter--
INSERT OVERWRITE TABLE srdi_mart.dws_sr_data_warehouse_platform_exp_state_level_nmv_1d
PARTITION (exp_type = 'dim_join', grass_region = ${grass_region}, local_date)
select
    state
    ,platform
    ,is_ads
    ,scenario_tag
    ,feature_detail
    ,target_type
    ,exp_group_id

    ,net_order_uu
    ,net_order_cnt
    ,nmv

    ,local_date
from explode_metric_table_${grass_region_without_quote}
;
